    if ((samples == NULL) || (weights == NULL) || (direction == NULL) || (resultant == NULL)) {
        *direction = (adcs_vec3_t){0, 0, 0};
        *resultant = 0.0;
        return ADCS_E_NULL;
    }

    if (count < 2 || count > 32) {
        *direction = (adcs_vec3_t){0, 0, 0};
        *resultant = 0.0;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t s = {0, 0, 0};
    double total_weight = 0.0;
    adcs_vec3_t u_i;
    double norm_sample;

    for (size_t i = 0; i < count; i++) {
        if (!isfinite(weights[i]) || weights[i] <= 0.0) {
            *direction = (adcs_vec3_t){0, 0, 0};
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        if (!isfinite(samples[i].x) || !isfinite(samples[i].y) || !isfinite(samples[i].z)) {
            *direction = (adcs_vec3_t){0, 0, 0};
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        norm_sample = adcs_vec3_norm(&samples[i]);

        if (norm_sample <= ADCS_EPS_NORM) {
            *direction = (adcs_vec3_t){0, 0, 0};
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        u_i.x = samples[i].x / norm_sample;
        u_i.y = samples[i].y / norm_sample;
        u_i.z = samples[i].z / norm_sample;

        s.x += weights[i] * u_i.x;
        s.y += weights[i] * u_i.y;
        s.z += weights[i] * u_i.z;

        total_weight += weights[i];
    }

    double norm_s = adcs_vec3_norm(&s);
    if (norm_s <= ADCS_EPS_COLLINEAR) {
        *direction = (adcs_vec3_t){0, 0, 0};
        *resultant = 0.0;
        return ADCS_E_DEGENERATE;
    }

    direction->x = s.x / norm_s;
    direction->y = s.y / norm_s;
    direction->z = s.z / norm_s;

    *resultant = norm_s / total_weight;

    return ADCS_OK;
}

