    if ((samples == NULL) || (weights == NULL) || (direction == NULL) || (resultant == NULL)) {
        return ADCS_E_NULL;
    }
    if (count < 2U || count > 32U) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t s = {0.0, 0.0, 0.0};
    double total_weight = 0.0;
    adcs_vec3_t u_i;
    double sample_norm;

    for (size_t i = 0; i < count; i++) {
        if ((!isfinite(weights[i])) || (weights[i] <= 0.0)) {
            return ADCS_E_RANGE;
        }
        if (!adcs_is_finite_vec3(&samples[i])) {
            return ADCS_E_RANGE;
        }

        sample_norm = adcs_vec3_norm(&samples[i]);
        if (sample_norm <= ADCS_EPS_NORM) {
            return ADCS_E_RANGE;
        }

        u_i = adcs_vec3_scale(&samples[i], 1.0 / sample_norm);
        s = adcs_vec3_add(&s, &adcs_vec3_scale(&u_i, weights[i]));
        total_weight += weights[i];
    }

    double norm_s = adcs_vec3_norm(&s);
    if (norm_s <= ADCS_EPS_COLLINEAR) {
        return ADCS_E_DEGENERATE;
    }

    *resultant = norm_s / total_weight;

    // direction is normalized s
    *direction = adcs_vec3_scale(&s, 1.0 / norm_s);

    return ADCS_OK;
}

