    adcs_vec3_t s = {0.0, 0.0, 0.0};
    double total_weight = 0.0;
    size_t i;
    adcs_vec3_t u;
    adcs_status_t status;

    /* Check for NULL pointers */
    if ((samples == NULL) || (weights == NULL) || (direction == NULL) || (resultant == NULL)) {
        direction->x = 0.0;
        direction->y = 0.0;
        direction->z = 0.0;
        *resultant = 0.0;
        return ADCS_E_NULL;
    }

    /* Check count range */
    if (count < 2U || count > 32U) {
        direction->x = 0.0;
        direction->y = 0.0;
        direction->z = 0.0;
        *resultant = 0.0;
        return ADCS_E_RANGE;
    }

    /* Iterate through samples and weights */
    for (i = 0; i < count; i++) {
        /* Check weight validity: finite and positive */
        if ((!isfinite(weights[i])) || (weights[i] <= 0.0)) {
            direction->x = 0.0;
            direction->y = 0.0;
            direction->z = 0.0;
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        /* Check sample validity: finite */
        if (!adcs_is_finite_vec3(&samples[i])) {
            direction->x = 0.0;
            direction->y = 0.0;
            direction->z = 0.0;
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        /* Normalize sample and check for small norm */
        status = adcs_vec3_normalize(&samples[i], ADCS_EPS_NORM, &u);
        if (status != ADCS_OK) {
            direction->x = 0.0;
            direction->y = 0.0;
            direction->z = 0.0;
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        /* Accumulate weighted direction and total weight */
        total_weight += weights[i];
        s = adcs_vec3_add(&s, &adcs_vec3_scale(&u, weights[i]));
    }

    /* Calculate resultant magnitude */
    double norm_s = adcs_vec3_norm(&s);

    /* Check for degenerate/cancelling resultant */
    if (norm_s <= ADCS_EPS_COLLINEAR) {
        direction->x = 0.0;
        direction->y = 0.0;
        direction->z = 0.0;
        *resultant = 0.0;
        return ADCS_E_DEGENERATE;
    }

    /* Normalize the resultant vector to get direction */
    status = adcs_vec3_normalize(&s, ADCS_EPS_NORM, direction);

    /* Calculate resultant magnitude divided by total weight */
    *resultant = norm_s / total_weight;

    return status;
}

